/**
 * Сервис-воркер для кэширования статических ресурсов и отображения
 * офлайн-страницы при отсутствии сети.
 *
 * Стратегия кэширования:
 * - Статические ресурсы (HTML, CSS, JS, изображения и т.д.) кэшируются
 *   по стратегии "Cache First" с фоновым обновлением (stale-while-revalidate).
 * - При отсутствии сети и отсутствии ресурса в кэше показывается
 *   офлайн-страница.
 */

// Имя кэша для статических ресурсов
const CACHE_NAME = 'static-cache-v1';

// Имя кэша для офлайн-страницы
const OFFLINE_CACHE_NAME = 'offline-cache-v1';

// URL офлайн-страницы
const OFFLINE_URL = '/offline.html';

// Список ресурсов, которые нужно закэшировать при установке воркера
const PRECACHE_ASSETS: string[] = [
  '/',
  '/index.html',
  '/offline.html',
  '/styles.css',
  '/app.js',
  '/favicon.ico',
];

/**
 * Обработчик события установки сервис-воркера.
 * Вызывается при первой регистрации воркера или при обновлении скрипта воркера.
 *
 * В этом обработчике:
 * 1. Открывается кэш с указанным именем.
 * 2. Все ресурсы из списка PRECACHE_ASSETS добавляются в кэш.
 * 3. Старые версии кэшей удаляются.
 * 4. Вызывается skipWaiting для немедленного активации нового воркера.
 */
self.addEventListener('install', (event: ExtendableEvent) => {
  // event.waitUntil() позволяет браузеру дождаться завершения асинхронной операции
  // перед завершением этапа установки. Если промис отклоняется, установка считается неудачной.
  event.waitUntil(
    (async () => {
      try {
        // Открываем кэш для статических ресурсов
        const cache = await caches.open(CACHE_NAME);

        // Добавляем все предопределённые ресурсы в кэш.
        // cache.addAll() выполняет запросы к каждому URL и сохраняет ответы.
        // Если хотя бы один запрос завершится ошибкой, весь промис отклонится.
        await cache.addAll(PRECACHE_ASSETS);

        // skipWaiting() заставляет новый сервис-воркер немедленно стать активным,
        // не дожидаясь закрытия всех вкладок с предыдущей версией воркера.
        // Это полезно для быстрого обновления, но может привести к несогласованности
        // между HTML и JS/CSS, если они обновляются одновременно.
        await self.skipWaiting();
      } catch (error) {
        console.error('[SW] Ошибка при установке:', error);
        throw error; // Пробрасываем ошибку, чтобы установка была помечена как неудачная
      }
    })()
  );
});

