public void applyCors(HttpServletRequest req, HttpServletResponse resp) {
    // Получаем заголовок Origin из входящего запроса.
    // Этот заголовок отправляет браузер, указывая источник (домен) запроса.
    String origin = req.getHeader("Origin");

    // Если заголовок Origin отсутствует, значит запрос не является кросс-доменным
    // (или это запрос от того же источника, или запрос без CORS).
    // В этом случае нет необходимости применять CORS-заголовки, просто выходим.
    if (origin == null) {
        return;
    }

    // Проверяем, разрешён ли данный источник (origin).
    // Разрешён, если:
    // 1. Он явно указан в списке разрешённых источников (allowedOrigins), ИЛИ
    // 2. Включена поддержка поддоменов (allowSubdomains) и origin является поддоменом базового домена (baseDomain).
    //    Например, если baseDomain = "example.com", то "sub.example.com" будет разрешён.
    boolean allowed = allowedOrigins.contains(origin)
        || (allowSubdomains && origin.endsWith("." + baseDomain));

    // Если источник не разрешён, возвращаем ошибку 403 Forbidden и прекращаем обработку.
    // Это предотвращает доступ с неавторизованных доменов.
    if (!allowed) {
        resp.setStatus(HttpServletResponse.SC_FORBIDDEN);
        return;
    }

    // Устанавливаем заголовок Access-Control-Allow-Origin, равный origin запроса.
    // Это говорит браузеру, что запрос с данного источника разрешён.
    // Использование конкретного origin вместо "*" необходимо, если используются credentials (куки, авторизация).
    resp.setHeader("Access-Control-Allow-Origin", origin);

    // Разрешаем отправку credentials (куки, заголовки авторизации) в кросс-доменных запросах.
    // Это необходимо, если клиент должен отправлять куки или заголовок Authorization.
    resp.setHeader("Access-Control-Allow-Credentials", "true");

    // Добавляем заголовок Vary: Origin.
    // Это важно для корректной работы кэширования: сервер должен кэшировать разные ответы
    // для разных значений заголовка Origin, так как ответ зависит от него.
    resp.addHeader("Vary", "Origin");

    // Если метод запроса — OPTIONS, это предварительный (preflight) запрос CORS.
    // Браузер отправляет его перед основным запросом, чтобы проверить, разрешён ли кросс-доменный запрос.
    if ("OPTIONS".equalsIgnoreCase(req.getMethod())) {
