public static string NextVersion(string current, IReadOnlyList<string> commitTitles)
{
    // Удаляем префикс 'v' (если есть), разбиваем строку по точкам и преобразуем части в целые числа
    var parts = current.TrimStart('v').Split('.').Select(int.Parse).ToArray();

    // Проверяем, что версия имеет формат из трёх чисел (мажор.минор.патч)
    if (parts.Length != 3)
        throw new FormatException($"Bad version: {current}");

    // Распаковываем компоненты версии в отдельные переменные для удобства
    var (major, minor, patch) = (parts[0], parts[1], parts[2]);

    // Проверяем наличие "BREAKING CHANGE" в заголовках коммитов или наличие '!' перед двоеточием
    // (согласно конвенции Conventional Commits, '!' указывает на breaking change)
    // Если найдено — это мажорное обновление
    if (commitTitles.Any(t => t.Contains("BREAKING CHANGE") || t.Split(':')[0].EndsWith("!")))
    {
        // Особый случай: если текущая мажорная версия равна 0, то по конвенции SemVer
        // breaking changes увеличивают минорную версию, а не мажорную
        return major == 0 ? $"v0.{minor + 1}.0" : $"v{major + 1}.0.0";
    }

    // Проверяем наличие коммитов с типом "feat" (новые функции)
    // Если найдено — это минорное обновление
    if (commitTitles.Any(t => t.StartsWith("feat")))
        return $"v{major}.{minor + 1}.0";

    // Если нет ни breaking changes, ни новых функций, и список коммитов пуст —
    // версия остаётся без изменений
    if (commitTitles.Count == 0)
        return current;

    // Во всех остальных случаях (например, только фиксы, рефакторинги и т.п.)
    // делаем патч-обновление
    return $"v{major}.{minor}.{patch + 1}";
}
```

