func run(srv *http.Server, timeout time.Duration) error {
	// Создаем буферизованный канал для получения ошибок из горутини сервера.
	// Буфер размером 1 гарантирует, что горутина не заблокируется, если основной
	// поток уже завершил работу (например, получил сигнал остановки).
	errCh := make(chan error, 1)

	// Запускаем сервер в отдельной горутине, чтобы не блокировать основной поток.
	go func() {
		// Запускаем HTTP-сервер. ListenAndServe блокирует выполнение до остановки сервера.
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			// Если ошибка не связана с штатным закрытием сервера (например, ошибка привязки к порту),
			// отправляем её в канал для обработки в основном потоке.
			errCh <- err
		}
	}()

	// Создаем канал для приема сигналов операционной системы.
	stop := make(chan os.Signal, 1)
	// Регистрируем обработчик сигналов SIGINT (Ctrl+C) и SIGTERM (запрос на завершение процесса).
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)

	// Ожидаем либо ошибку запуска сервера, либо сигнал остановки.
	select {
	case err := <-errCh:
		// Если сервер завершился с ошибкой (не штатно), возвращаем эту ошибку.
		return err
	case <-stop:
		// Если получен сигнал остановки, продолжаем выполнение для корректного завершения.
	}

	// Создаем контекст с таймаутом для graceful shutdown.
	// Это гарантирует, что процесс завершения не зависнет бесконечно, если какие-то соединения
	// не закроются вовремя.
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	// Инициируем корректное завершение работы сервера:
	// сервер перестает принимать новые соединения, но дает время существующим
	// соединениям завершить обработку запросов (в пределах таймаута).
	return srv.Shutdown(ctx)
}
