// Определяем герметичный интерфейс Route, который представляет собой
// все возможные маршруты (экраны) в приложении.
// Использование sealed interface гарантирует, что все реализации известны
// на этапе компиляции, что позволяет использовать исчерпывающий when.
sealed interface Route {
    // Маршрут для просмотра конкретного товара по его ID
    data class Product(val id: Long) : Route

    // Маршрут для результатов поиска с запросом и номером страницы
    data class Search(val query: String, val page: Int) : Route

    // Маршрут главной страницы (синглтон, так как не требует данных)
    object Home : Route
}

/**
 * Функция для парсинга deep link (URI) и преобразования его в объект Route.
 * @param uri - входящий URI, который нужно разобрать
 * @return - соответствующий объект Route или Route.Home, если URI не распознан
 */
fun parseDeepLink(uri: Uri): Route {
    // Проверяем, что схема URI или хост соответствуют ожидаемым значениям.
    // Если ни схема "shop", ни хост "shop.example.com" не совпадают,
    // считаем, что это невалидный deep link, и возвращаем главную страницу.
    if (uri.scheme != "shop" && uri.host != "shop.example.com") return Route.Home

    // Получаем список сегментов пути из URI (например, для "/product/123"
    // это будет ["product", "123"])
    val segments = uri.pathSegments

    // Анализируем первый сегмент пути, чтобы определить тип маршрута
    return when (segments.firstOrNull()) {
        // Если первый сегмент "product", пытаемся извлечь ID товара из второго сегмента
        "product" -> segments.getOrNull(1)?.toLongOrNull()?.let { Route.Product(it) } ?: Route.Home

        // Если первый сегмент "search", извлекаем параметры поиска из query-строки
        "search" -> {
            // Получаем параметр "q" (запрос), удаляем пробелы по краям.
            // Если параметр отсутствует, используем пустую строку.
            val q = uri.getQueryParameter("q").orEmpty().trim()

            // Получаем параметр "page" (номер страницы), преобразуем в Int.
            // Если параметр отсутствует или не является числом, используем 1.
            // coerceAtLeast(1) гарантирует, что номер страницы не будет меньше 1.
            val page = uri.getQueryParameter("page")?.toIntOrNull()?.coerceAtLeast(1) ?: 1

            // Если запрос пустой, возвращаем главную страницу, иначе — маршрут поиска
            if (q.isEmpty()) Route.Home else Route.Search(q, page)
        }

        // Для всех остальных случаев (неизвестный путь) возвращаем главную страницу
        else -> Route.Home
    }
}
```

